// All-starts exact latent-F receiver, followed by finite-domain absolute interval tiling.
// Input is generated by lp2_geb_line_tiling_prepare.cjs; no external book text is emitted.
#include <algorithm>
#include <array>
#include <cassert>
#include <cmath>
#include <cstdint>
#include <fstream>
#include <functional>
#include <iomanip>
#include <iostream>
#include <limits>
#include <map>
#include <numeric>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <vector>
using namespace std;
constexpr int A=29, CAP=256, NEG=-100000000;
vector<int> K; double lu[A],lb[A*A],lt[A*A*A];
uint32_t seed=0x33012721u;
uint32_t rnd(){seed^=seed<<13;seed^=seed>>17;seed^=seed<<5;return seed;}
vector<int> readvec(istream& in){int n;if(!(in>>n)||n<0)throw runtime_error("input");vector<int> v(n);for(int& x:v){in>>x;if(x<0||x>=A)throw runtime_error("symbol");}return v;}
int mod(int x){return x<0?x+A:x>=A?x-A:x;}
inline double score(int i,int x,int y,int p){return i==0?lu[p]:i==1?lb[y*A+p]:lt[(x*A+y)*A+p];}
double scoreP(const vector<int>& P){double s=0;int x=0,y=0;for(int i=0;i<(int)P.size();i++){s+=score(i,x,y,P[i]);x=y;y=P[i];}return s;}
struct Enc{vector<int>C;int end;};
Enc emit(const vector<int>& P,int j){vector<int>C;for(int p:P){if(!p)C.push_back(0);else {if(j>=(int)K.size())throw runtime_error("key end");C.push_back(mod(p+K[j++]));}}return {C,j};}
struct Edge{int start,end,id=-1;double s;vector<int>P;};
bool better(const Edge&a,const Edge&b){if(a.s!=b.s)return a.s>b.s;if(a.start!=b.start)return a.start<b.start;return a.end<b.end;}
struct Scan{vector<Edge>top;long long paths=0,origins=0,above=0;};
struct Scanner{
 const vector<int>&C; const vector<int>*truth;int trueStart; double truthScore;vector<int>P;int start;double ob;Scan out;
 Scanner(const vector<int>&c,const vector<int>*t=nullptr,int ts=-1):C(c),truth(t),trueStart(ts),truthScore(t?scoreP(*t):0),P(c.size()){}
 void save(int j,double s){
   out.paths++;ob=max(ob,s);
   if(out.top.size()==CAP && (s<out.top.back().s || (s==out.top.back().s&&start>out.top.back().start)))return;
   Edge e{start,j,-1,s,P};
   for(auto it=out.top.begin();it!=out.top.end();++it)if(it->start==start&&it->end==j){if(!better(e,*it))return;out.top.erase(it);break;}
   auto pos=lower_bound(out.top.begin(),out.top.end(),e,better);out.top.insert(pos,move(e));if(out.top.size()>CAP)out.top.pop_back();
 }
 void walk(int i,int j,int x,int y,double s){
   for(;i<(int)C.size();i++){
     int c=C[i];
     if(c==0){P[i]=0;walk(i+1,j,y,0,s+score(i,x,y,0));}
     if(j>=(int)K.size())return;
     int p=mod(c-K[j]);if(p==0)return;
     P[i]=p;s+=score(i,x,y,p);x=y;y=p;j++;
   }
   save(j,s);
 }
 Scan all(){
   for(start=0;start<(int)K.size();start++){ob=-numeric_limits<double>::infinity();walk(0,start,0,0,0);if(isfinite(ob)){out.origins++;if(truth&&ob>truthScore+1e-9)out.above++;}}
   if(out.top.empty())throw runtime_error("no legal line");
   for(const Edge&e:out.top){auto r=emit(e.P,e.start);if(r.C!=C||r.end!=e.end)throw runtime_error("bad replay");}
   return move(out);
 }
 vector<Edge> at(int j){
   start=j;ob=-numeric_limits<double>::infinity();out=Scan{};walk(0,j,0,0,0);
   for(const Edge&e:out.top){auto r=emit(e.P,e.start);if(r.C!=C||r.end!=e.end)throw runtime_error("bad replay");}
   return move(out.top);
 }
};
struct Tiling{long long nodes=0,solutions=0;double best=-numeric_limits<double>::infinity();vector<Edge>path;};
Tiling tile(const vector<Scan>&scans){
 unordered_map<int,vector<Edge>> by;for(int id=0;id<(int)scans.size();id++)for(auto e:scans[id].top){e.id=id;by[e.start].push_back(move(e));}
 Tiling t;vector<Edge> path;int full=(1<<scans.size())-1;
 function<void(int,int,double)> dfs=[&](int j,int mask,double s){t.nodes++;if(mask==full){t.solutions++;if(s>t.best){t.best=s;t.path=path;}return;}auto it=by.find(j);if(it==by.end())return;for(const Edge&e:it->second){if(mask&(1<<e.id))continue;path.push_back(e);dfs(e.end,mask|(1<<e.id),s+e.s);path.pop_back();}};
 vector<int>starts;for(auto& x:by)starts.push_back(x.first);sort(starts.begin(),starts.end());for(int j:starts)dfs(j,0,0);return t;
}
// Exact conditional reconstruction given any one of the top sixteen line intervals.
// For each anchor, other lines may occupy every legal neighboring offset, irrespective of their ranks.
struct Node{double s;int prev;const Edge* e;};
Tiling anchoredTile(const vector<Scan>&scans,const vector<vector<int>>&C){
 const int n=C.size(),full=(1<<n)-1,total=accumulate(C.begin(),C.end(),0,[](int s,const auto&v){return s+(int)v.size();});
 Tiling best;
 for(int a=0;a<n;a++)for(int k=0;k<min(16,(int)scans[a].top.size());k++){
   Edge anchor=scans[a].top[k];anchor.id=a;const int remaining=full^(1<<a);
   const int lo=max(0,anchor.start-total),hi=min((int)K.size(),anchor.end+total),width=hi-lo+1;
   vector<vector<vector<Edge>>> out(n,vector<vector<Edge>>(width));
   vector<int>len(n),zeros(n);
   for(int id=0;id<n;id++)if(id!=a){
     len[id]=C[id].size();zeros[id]=count(C[id].begin(),C[id].end(),0);
     for(int j=lo;j<hi;j++){
       auto es=Scanner(C[id]).at(j);for(auto&e:es)if(e.end<=hi){e.id=id;out[id][j-lo].push_back(move(e));}
     }
   }
   using Map=unordered_map<int,Node>;
   vector<Map> F(1<<n),B(1<<n);
   F[0].emplace(anchor.end,Node{0,-1,nullptr});B[0].emplace(anchor.start,Node{0,-1,nullptr});
   auto put=[](Map&m,int pos,double s,int prev,const Edge*e){
     auto it=m.find(pos);if(it==m.end())m.emplace(pos,Node{s,prev,e});else if(s>it->second.s)it->second={s,prev,e};
   };
   for(int mask=0;mask<=full;mask++){
     if(mask&(1<<a))continue;
     for(auto&kv:F[mask]){int j=kv.first;double s=kv.second.s;best.nodes++;
       for(int id=0;id<n;id++)if(id!=a&&!(mask&(1<<id)))for(const Edge&e:out[id][j-lo])put(F[mask|(1<<id)],e.end,s+e.s,j,&e);
     }
     for(auto&kv:B[mask]){int j=kv.first;double s=kv.second.s;best.nodes++;
       for(int id=0;id<n;id++)if(id!=a&&!(mask&(1<<id))){
         for(int at=max(lo,j-len[id]);at<=min(hi,j-len[id]+zeros[id]);at++)for(const Edge&e:out[id][at-lo])if(e.end==j)put(B[mask|(1<<id)],at,s+e.s,j,&e);
       }
     }
   }
   auto maxpos=[](const Map&m){int p=-1;double s=-numeric_limits<double>::infinity();for(auto&kv:m)if(kv.second.s>s||(kv.second.s==s&&kv.first<p)){p=kv.first;s=kv.second.s;}return pair<int,double>{p,s};};
   for(int left=0;left<=remaining;left++){
     if(left&~remaining)continue;const int right=remaining^left;
     if(B[left].empty()||F[right].empty())continue;
     auto [bp,bs]=maxpos(B[left]);auto[fp,fs]=maxpos(F[right]);best.solutions++;
     const double s=bs+anchor.s+fs;if(s<=best.best)continue;best.best=s;best.path.clear();
     int mask=left,pos=bp;while(mask){const Node&u=B[mask].at(pos);best.path.push_back(*u.e);mask^=1<<u.e->id;pos=u.prev;}
     best.path.push_back(anchor);
     vector<Edge> tail;mask=right;pos=fp;while(mask){const Node&u=F[mask].at(pos);tail.push_back(*u.e);mask^=1<<u.e->id;pos=u.prev;}
     reverse(tail.begin(),tail.end());best.path.insert(best.path.end(),tail.begin(),tail.end());
   }
 }
 int mask=0,previous=-1;for(const Edge&e:best.path){if(mask&(1<<e.id))throw runtime_error("duplicate line");mask|=1<<e.id;if(previous>=0&&previous!=e.start)throw runtime_error("broken interval");auto enc=emit(e.P,e.start);if(enc.C!=C[e.id]||enc.end!=e.end)throw runtime_error("anchor replay");previous=e.end;}
 if(!best.path.empty()&&mask!=full)throw runtime_error("incomplete anchor replay");
 return best;
}
Tiling continueAt(const vector<vector<int>>& C,int start){
 Tiling t;vector<Edge>path;const int full=(1<<C.size())-1;
 function<void(int,int,double)> dfs=[&](int j,int mask,double s){t.nodes++;if(mask==full){t.solutions++;if(s>t.best){t.best=s;t.path=path;}return;}for(int id=0;id<(int)C.size();id++)if(!(mask&(1<<id))){auto es=Scanner(C[id]).at(j);for(auto&e:es){e.id=id;path.push_back(e);dfs(e.end,mask|(1<<id),s+e.s);path.pop_back();}}};
 dfs(start,0,0);return t;
}
vector<int> shuffled(vector<int>C){vector<int>i;for(int j=0;j<(int)C.size();j++)if(C[j])i.push_back(j);for(int j=(int)i.size()-1;j>0;j--)swap(C[i[j]],C[i[rnd()%(j+1)]]);return C;}
string textP(const vector<int>&P){static const char* t[]={"F","U","TH","O","R","C","G","W","H","N","I","J","EO","P","X","S","T","B","E","M","L","NG","OE","D","A","AE","Y","IA","EA"};string s;for(int p:P)s+=t[p];return s;}
void jsonpath(const Tiling&t,const vector<vector<int>>*P=nullptr,const vector<int>*starts=nullptr,const vector<int>*ends=nullptr){
 cout<<"{\"nodes\":"<<t.nodes<<",\"solutions\":"<<t.solutions;
 if(t.path.empty()){cout<<",\"best\":null}";return;}
 cout<<",\"best\":"<<t.best<<",\"start\":"<<t.path.front().start<<",\"end\":"<<t.path.back().end<<",\"order\":[";
 for(int i=0;i<(int)t.path.size();i++){if(i)cout<<",";cout<<t.path[i].id;}cout<<"],\"plaintext\":\"";for(const auto&e:t.path)cout<<textP(e.P);cout<<"\"";
 if(P){int correct=0,intervals=0;bool order=true;for(int i=0;i<(int)t.path.size();i++){auto&e=t.path[i];order&=e.id==i;for(int j=0;j<(int)e.P.size();j++)correct+=e.P[j]==(*P)[e.id][j];intervals+=e.start==(*starts)[e.id]&&e.end==(*ends)[e.id];}cout<<",\"correctRunes\":"<<correct<<",\"exactIntervals\":"<<intervals<<",\"exactOrder\":"<<(order?"true":"false");}
 cout<<"}";
}
void run(const string&name,const vector<vector<int>>&fit,const vector<vector<int>>&hold,const vector<vector<int>>*fitP=nullptr,const vector<vector<int>>*holdP=nullptr,const vector<int>*fitStarts=nullptr,const vector<int>*fitEnds=nullptr,const vector<int>*holdStarts=nullptr,const vector<int>*holdEnds=nullptr){
 vector<Scan> scans;double means=0;int exact=0,retained=0;cout<<"{\"name\":\""<<name<<"\",\"lines\":[";
 for(int i=0;i<(int)fit.size();i++){
   auto r=Scanner(fit[i],fitP?&(*fitP)[i]:nullptr,fitStarts?(*fitStarts)[i]:-1).all();
   auto&e=r.top.front();means+=e.s/fit[i].size();if(i)cout<<",";cout<<"{\"length\":"<<fit[i].size()<<",\"best\":"<<e.s/fit[i].size()<<",\"start\":"<<e.start<<",\"end\":"<<e.end<<",\"origins\":"<<r.origins<<",\"paths\":"<<r.paths<<",\"text\":\""<<textP(e.P)<<"\"";
   if(fitP){bool hit=e.start==(*fitStarts)[i]&&e.P==(*fitP)[i],iv=false;for(auto&x:r.top)iv|=x.start==(*fitStarts)[i]&&x.end==(*fitEnds)[i];exact+=hit;retained+=iv;cout<<",\"rank\":"<<r.above+1<<",\"exact\":"<<(hit?"true":"false")<<",\"intervalRetained\":"<<(iv?"true":"false");}
   cout<<"}";scans.push_back(move(r));
 }
 auto t=tile(scans);cout<<"],\"meanBest\":"<<means/fit.size()<<",\"exactIndependent\":"<<exact<<",\"retained\":"<<retained<<",\"fit\":";jsonpath(t,fitP,fitStarts,fitEnds);
 cout<<",\"holdout\":";if(t.path.empty())cout<<"null";else{auto h=continueAt(hold,t.path.back().end);jsonpath(h,holdP,holdStarts,holdEnds);}
 auto a=anchoredTile(scans,fit);cout<<",\"anchoredFit\":";jsonpath(a,fitP,fitStarts,fitEnds);cout<<",\"anchoredHoldout\":";if(a.path.empty())cout<<"null";else{auto h=continueAt(hold,a.path.back().end);jsonpath(h,holdP,holdStarts,holdEnds);}cout<<"}";
}
int main(int argc,char**argv){
 if(argc!=2)throw runtime_error("input path");ifstream f(argv[1]);K=readvec(f);vector<vector<int>>train;for(int i=0;i<4;i++)train.push_back(readvec(f));auto donor=readvec(f);vector<vector<int>>fit,hold;for(int i=0;i<11;i++)fit.push_back(readvec(f));for(int i=0;i<4;i++)hold.push_back(readvec(f));
 double u[A]={},b[A*A]={},tr[A*A*A]={},bn[A]={},tn[A*A]={};int T=0;
 for(auto&P:train)for(int i=0;i<(int)P.size();i++){int p=P[i];u[p]++;T++;if(i){b[P[i-1]*A+p]++;bn[P[i-1]]++;}if(i>=2){int z=P[i-2]*A+P[i-1];tr[z*A+p]++;tn[z]++;}}
 for(int x=0;x<A;x++){u[x]=(u[x]+.5)/(T+.5*A);lu[x]=log(u[x]);}
 for(int x=0;x<A;x++)for(int y=0;y<A;y++){b[x*A+y]=(b[x*A+y]+5*u[y])/(bn[x]+5);lb[x*A+y]=log(b[x*A+y]);}
 for(int x=0;x<A*A;x++)for(int y=0;y<A;y++)lt[x*A+y]=log((tr[x*A+y]+8*b[(x%A)*A+y])/(tn[x]+8));
 cout<<setprecision(10)<<"{\"keyLength\":"<<K.size()<<",\"cap\":"<<CAP<<",\"cases\":[";
 for(int k=0;k<2;k++){int off=k*308,j=k?500000:100000;vector<vector<int>>P,Q,C,D;vector<int>ps,pe,qs,qe;
   for(auto&v:fit){P.emplace_back(donor.begin()+off,donor.begin()+off+v.size());off+=v.size();ps.push_back(j);auto e=emit(P.back(),j);j=e.end;pe.push_back(j);C.push_back(move(e.C));}
   for(auto&v:hold){Q.emplace_back(donor.begin()+off,donor.begin()+off+v.size());off+=v.size();qs.push_back(j);auto e=emit(Q.back(),j);j=e.end;qe.push_back(j);D.push_back(move(e.C));}
   if(k)cout<<",";run(k?"plant500000":"plant100000",C,D,&P,&Q,&ps,&pe,&qs,&qe);
   for(auto&v:C)v=shuffled(v);for(auto&v:D)v=shuffled(v);cout<<",";run(k?"null500000":"null100000",C,D);
 }
 cout<<",";run("original",fit,hold);for(auto&v:fit)v=shuffled(v);for(auto&v:hold)v=shuffled(v);cout<<",";run("originalNull",fit,hold);cout<<"]}\n";
}
